<template>
  <div class="ops-page">
    <header class="page-head"><div><div class="kicker">FAN OPERATIONS</div><h1>运营工作台</h1><p>管理商家合作、推广内容与带货结果</p></div><el-button @click="reload">刷新数据</el-button></header>
    <el-tabs v-model="tab" class="ops-tabs" @tab-change="loadTab">
      <el-tab-pane label="商家管理" name="merchants">
        <el-table :data="merchants" stripe><el-table-column prop="name" label="商家" min-width="160"/><el-table-column prop="contact_name" label="联系人"/><el-table-column prop="contact_phone" label="联系电话"/><el-table-column label="资质状态"><template #default="s"><el-tag :type="tagType(s.row.qualification_status)">{{ status(s.row.qualification_status) }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="220"><template #default="s"><el-button v-if="s.row.document_count" link type="primary" @click="download(`/fan/merchant/${s.row.id}/qualification`,'商家资质')">查看资质</el-button><template v-if="s.row.qualification_status==='PENDING'"><el-button link type="success" :disabled="!s.row.document_count" @click="reviewMerchant(s.row,true)">通过</el-button><el-button link type="danger" @click="reviewMerchant(s.row,false)">驳回</el-button></template></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="商品管理" name="products">
        <el-table :data="products" stripe><el-table-column prop="name" label="商品" min-width="140"/><el-table-column prop="merchant_name" label="所属商家"/><el-table-column prop="description" label="商品说明" show-overflow-tooltip/><el-table-column label="状态"><template #default="s"><el-tag :type="tagType(s.row.status)">{{ status(s.row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="210"><template #default="s"><el-button link type="primary" @click="productAssets(s.row)">查看素材</el-button><template v-if="s.row.status==='PENDING'"><el-button link type="success" @click="reviewProduct(s.row,true)">通过</el-button><el-button link type="danger" @click="reviewProduct(s.row,false)">驳回</el-button></template></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="合作订单" name="orders">
        <div class="toolbar"><el-button type="primary" @click="openOrder">创建合作订单</el-button></div>
        <el-table :data="orders" stripe><el-table-column prop="order_no" label="订单号" min-width="230" show-overflow-tooltip/><el-table-column prop="merchant_name" label="商家"/><el-table-column label="状态"><template #default="s">{{ status(s.row.status) }}</template></el-table-column><el-table-column prop="agreed_publish_count" label="约定发布"/><el-table-column prop="quoted_fee" label="基础费 (USD)"/><el-table-column label="操作" min-width="250"><template #default="s"><el-button link type="primary" @click="openVideos(s.row)">视频管理</el-button><el-button link type="primary" @click="openSummary(s.row)">带货效果</el-button><el-button v-if="s.row.status==='IN_PROGRESS'" link type="primary" @click="openFee(s.row)">费用调整</el-button><el-button v-if="s.row.status==='IN_PROGRESS'" link type="primary" @click="openSettlement(s.row)">创建结算</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="带货数据" name="imports">
        <el-form :inline="true" class="import-form"><el-form-item label="数据来源"><el-input v-model="imp.source" placeholder="如 platform_a" /></el-form-item><el-form-item label="统计截止时间 (UTC)"><el-date-picker v-model="imp.snapshotAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="数据版本"><el-input-number v-model="imp.sourceVersion" :min="1" :max="1000000" /></el-form-item><el-form-item><input type="file" accept=".xlsx" @change="importFile=$event.target.files[0]" /></el-form-item><el-form-item><el-button type="primary" @click="createImport">上传并预览</el-button></el-form-item></el-form>
        <p class="hint">表格前两列为“视频编号”和“最终GMV(USD)”，每行对应一条视频。</p>
        <el-table :data="imports" stripe><el-table-column prop="id" label="任务号" width="90"/><el-table-column prop="source" label="数据来源"/><el-table-column prop="snapshot_at" label="统计截止时间" min-width="180"/><el-table-column label="状态"><template #default="s">{{ status(s.row.state) }}</template></el-table-column><el-table-column prop="total_rows" label="记录数"/><el-table-column prop="error_message" label="处理信息" show-overflow-tooltip/><el-table-column label="操作" min-width="180"><template #default="s"><el-button link type="primary" @click="showImport(s.row)">查看</el-button><el-button v-if="s.row.state==='PREVIEW_READY'" link type="success" @click="confirmImport(s.row)">确认导入</el-button><el-button v-if="s.row.state==='FAILED'" link type="warning" @click="retryImport(s.row)">重试</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="结算管理" name="settlements">
        <el-table :data="settlements" stripe><el-table-column prop="order_no" label="订单号" min-width="220" show-overflow-tooltip/><el-table-column prop="final_gmv" label="GMV (USD)"/><el-table-column prop="commission" label="佣金 (USD)"/><el-table-column prop="service_fee" label="服务费 (USD)"/><el-table-column prop="receivable" label="应收 (USD)"/><el-table-column prop="received" label="已收 (USD)"/><el-table-column label="状态"><template #default="s">{{ status(s.row.state) }}</template></el-table-column><el-table-column label="操作" min-width="160"><template #default="s"><el-button v-if="s.row.state==='DRAFT'" link type="primary" @click="approveSettlement(s.row)">确认结算</el-button><el-button v-if="['OPEN','PARTIAL'].includes(s.row.state)" link type="primary" @click="openReceipt(s.row)">记录收款</el-button><el-button link type="primary" @click="settlementDetail(s.row)">详情</el-button></template></el-table-column></el-table>
      </el-tab-pane>
    </el-tabs>

    <el-dialog v-model="orderDialog" title="创建合作订单" width="650px"><el-form label-position="top"><el-form-item label="合作商家"><el-select v-model="orderForm.merchantId" filterable placeholder="选择已审核商家" @change="orderForm.productIds=[]"><el-option v-for="m in approvedMerchants" :key="m.id" :label="m.name" :value="m.id" /></el-select></el-form-item><el-form-item label="推广商品"><el-select v-model="orderForm.productIds" multiple filterable placeholder="选择商品"><el-option v-for="p in eligibleProducts" :key="p.id" :label="p.name" :value="p.id" /></el-select></el-form-item><div v-for="id in orderForm.productIds" :key="id" class="rate-row"><span>{{ products.find(p=>p.id===id)?.name }}</span><span>佣金比例</span><el-input-number v-model="rates[id]" :min="0" :max="100" :precision="2" /> <span>%</span></div><el-form-item label="约定发布次数"><el-input-number v-model="orderForm.agreedPublishCount" :min="1" /></el-form-item><el-form-item label="基础服务费 (USD)"><el-input-number v-model="orderForm.quotedFee" :min="0" :precision="2" /></el-form-item></el-form><template #footer><el-button @click="orderDialog=false">取消</el-button><el-button type="primary" @click="createOrder">创建订单</el-button></template></el-dialog>

    <el-dialog v-model="videoDialog" :title="`视频管理 · ${selectedOrder?.order_no||''}`" width="850px"><div class="toolbar"><el-button type="primary" :disabled="selectedOrder?.status!=='IN_PROGRESS'" @click="videoCreateDialog=true">登记视频</el-button><el-button @click="refreshVideos">刷新</el-button></div><el-table :data="videos"><el-table-column prop="external_video_id" label="视频编号"/><el-table-column prop="product_name_snapshot" label="推广商品"/><el-table-column prop="link_snapshot" label="商品链接" show-overflow-tooltip/><el-table-column prop="published_count" label="发布次数"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="openPublish(s.row)">登记发布</el-button></template></el-table-column></el-table></el-dialog>
    <el-dialog v-model="videoCreateDialog" title="登记视频" width="520px"><el-form label-position="top"><el-form-item label="推广商品及链接"><el-select v-model="videoForm.linkKey" placeholder="选择订单商品"><el-option v-for="i in items" :key="`${i.id}:${i.link_id}`" :label="`${i.product_name_snapshot} · ${i.url}`" :value="`${i.id}:${i.link_id}`" /></el-select></el-form-item><el-form-item label="外部视频编号"><el-input v-model="videoForm.externalVideoId" /></el-form-item></el-form><template #footer><el-button type="primary" @click="createVideo">保存</el-button></template></el-dialog>
    <el-dialog v-model="publishDialog" title="登记视频发布" width="520px"><el-form label-position="top"><el-form-item label="平台"><el-input v-model="publishForm.platform" /></el-form-item><el-form-item label="发布编号"><el-input v-model="publishForm.externalPublishId" /></el-form-item><el-form-item label="发布链接"><el-input v-model="publishForm.publishUrl" placeholder="https://" /></el-form-item><el-form-item label="发布时间 (UTC)"><el-date-picker v-model="publishForm.publishedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item></el-form><template #footer><el-button type="primary" @click="publishVideo">保存发布记录</el-button></template></el-dialog>
    <el-dialog v-model="summaryDialog" title="带货效果" width="650px"><el-form :inline="true"><el-form-item label="数据来源"><el-input v-model="summaryForm.source" /></el-form-item><el-form-item label="截止时间 (UTC)"><el-date-picker v-model="summaryForm.asOf" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-button type="primary" @click="loadSummary">查询</el-button></el-form><template v-if="summary"><div class="summary-line">最终 GMV：<strong>{{ summary.knownGmv }} USD</strong>　佣金：<strong>{{ summary.knownCommission }} USD</strong>　发布：<strong>{{ summary.publishedCount }} 次</strong></div><el-alert v-if="!summary.complete" title="部分视频尚无 GMV 数据" type="warning" :closable="false"/><el-table :data="summary.items"><el-table-column prop="product_name_snapshot" label="商品"/><el-table-column prop="video_count" label="视频数"/><el-table-column prop="known_gmv" label="GMV (USD)"/><el-table-column prop="known_commission" label="佣金 (USD)"/></el-table></template></el-dialog>
    <el-dialog v-model="feeDialog" title="提交费用调整" width="500px"><el-form label-position="top"><el-form-item label="实际服务费 (USD)"><el-input-number v-model="feeForm.actualFee" :min="0" :precision="2" /></el-form-item><el-form-item label="调整原因"><el-input v-model="feeForm.reason" type="textarea" /></el-form-item></el-form><template #footer><el-button type="primary" @click="submitFee">提交商家确认</el-button></template></el-dialog>
    <el-dialog v-model="settlementDialog" title="创建结算草稿" width="500px"><el-form label-position="top"><el-form-item label="数据来源"><el-input v-model="settlementForm.source" /></el-form-item><el-form-item label="统计截止时间 (UTC)"><el-date-picker v-model="settlementForm.snapshotAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item></el-form><template #footer><el-button type="primary" @click="createSettlement">创建</el-button></template></el-dialog>
    <el-dialog v-model="receiptDialog" title="记录收款" width="500px"><el-form label-position="top"><el-form-item label="收款金额 (USD)"><el-input-number v-model="receiptForm.amount" :min="0.01" :precision="2" /></el-form-item><el-form-item label="凭证编号"><el-input v-model="receiptForm.reference" /></el-form-item><el-form-item label="备注"><el-input v-model="receiptForm.note" /></el-form-item></el-form><template #footer><el-button type="primary" @click="recordReceipt">保存</el-button></template></el-dialog>
    <el-dialog v-model="detailDialog" :title="detailTitle" width="700px"><pre class="detail">{{ detailText }}</pre></el-dialog>
  </div>
</template>
<script setup>
import { ref, reactive, computed, onMounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import request from '@/utils/request'
const route=useRoute(), tab=ref(String(route.query.tab||'merchants'))
const merchants=ref([]),products=ref([]),orders=ref([]),imports=ref([]),settlements=ref([]),items=ref([]),videos=ref([]),summary=ref(null),selectedOrder=ref(null),selectedVideo=ref(null),selectedSettlement=ref(null),importFile=ref(null)
const orderDialog=ref(false),videoDialog=ref(false),videoCreateDialog=ref(false),publishDialog=ref(false),summaryDialog=ref(false),feeDialog=ref(false),settlementDialog=ref(false),receiptDialog=ref(false),detailDialog=ref(false),detailTitle=ref(''),detailText=ref('')
const orderForm=reactive({merchantId:null,productIds:[],agreedPublishCount:100,quotedFee:0}),rates=reactive({}),videoForm=reactive({linkKey:'',externalVideoId:''}),publishForm=reactive({platform:'',externalPublishId:'',publishUrl:'',publishedAt:''}),imp=reactive({source:'',snapshotAt:'',sourceVersion:1}),summaryForm=reactive({source:'',asOf:''}),feeForm=reactive({actualFee:0,reason:''}),settlementForm=reactive({source:'',snapshotAt:''}),receiptForm=reactive({amount:0.01,reference:'',note:''})
const approvedMerchants=computed(()=>merchants.value.filter(m=>m.qualification_status==='APPROVED'))
const eligibleProducts=computed(()=>products.value.filter(p=>p.merchant_id===orderForm.merchantId&&p.status==='APPROVED'))
const statusMap={PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',DRAFT:'草稿',PENDING_CONFIRMATION:'待商家确认',IN_PROGRESS:'执行中',PENDING_SETTLEMENT:'待结算',PREVIEW_QUEUED:'正在预览',PREVIEW_READY:'待确认',IMPORT_QUEUED:'正在导入',COMPLETED:'已完成',FAILED:'处理失败',OPEN:'待收款',PARTIAL:'部分收款',SETTLED:'已结算'}
const status=s=>statusMap[s]||s,tagType=s=>s==='APPROVED'?'success':s==='REJECTED'?'danger':'warning'
const get=async url=>(await request({url,method:'get'})).data, post=async(url,data)=>request({url,method:'post',data})
async function loadTab(name){if(name==='merchants')merchants.value=await get('/fan/ops/merchants');if(name==='products')products.value=await get('/fan/ops/products');if(name==='orders')orders.value=await get('/fan/ops/orders');if(name==='imports')imports.value=await get('/fan/ops/imports');if(name==='settlements')settlements.value=await get('/fan/ops/settlements')}
async function reload(){await loadTab(tab.value)}
async function askReason(){const r=await ElMessageBox.prompt('请输入驳回原因','驳回',{inputValidator:v=>!!v?.trim()||'请输入原因'});return r.value}
async function reviewMerchant(row,approved){let reason=approved?'':await askReason();if(approved)await ElMessageBox.confirm('确认该商家资质审核通过？','商家审核');await post(`/fan/merchant/${row.id}/review`,{version:row.version,approved,reason});ElMessage.success('审核完成');await reload()}
async function reviewProduct(row,approved){let reason=approved?'':await askReason();if(approved)await ElMessageBox.confirm('确认该商品审核通过？','商品审核');await post(`/fan/products/${row.id}/review`,{version:row.version,approved,reason});ElMessage.success('审核完成');await reload()}
async function download(url,name){const blob=await request({url,method:'get',responseType:'blob'});const head=new Uint8Array(await blob.slice(0,3).arrayBuffer());const extension=head[0]===255&&head[1]===216?'.jpg':'.png';const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name+extension;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000)}
async function productAssets(row){const a=await get(`/fan/products/review/${row.id}/assets`);if(!a.length){ElMessage.info('暂无素材');return}await download(`/fan/products/review/assets/${a[a.length-1].id}`,'商品素材')}
async function openOrder(){[merchants.value,products.value]=await Promise.all([get('/fan/ops/merchants'),get('/fan/ops/products')]);Object.assign(orderForm,{merchantId:null,productIds:[],agreedPublishCount:100,quotedFee:0});orderDialog.value=true}
async function createOrder(){if(!orderForm.merchantId||!orderForm.productIds.length){ElMessage.warning('请选择商家和商品');return}if(orderForm.productIds.some(id=>rates[id]===undefined||rates[id]===null)){ElMessage.warning('请填写每个商品的佣金比例');return}await post('/fan/orders',{merchantId:orderForm.merchantId,agreedPublishCount:orderForm.agreedPublishCount,quotedFee:orderForm.quotedFee,items:orderForm.productIds.map(id=>({productId:id,commissionRate:Number((rates[id]/100).toFixed(6))}))});orderDialog.value=false;ElMessage.success('订单已创建，等待商家确认');await reload()}
async function openVideos(row){selectedOrder.value=row;items.value=await get(`/fan/ops/orders/${row.id}/items`);await refreshVideos();videoDialog.value=true}
async function refreshVideos(){videos.value=await get(`/fan/ops/orders/${selectedOrder.value.id}/videos`)}
async function createVideo(){if(!videoForm.linkKey||!videoForm.externalVideoId.trim()){ElMessage.warning('请选择商品并填写视频编号');return}const [orderItemId,productLinkId]=videoForm.linkKey.split(':').map(Number);await post('/fan/videos',{orderItemId,productLinkId,externalVideoId:videoForm.externalVideoId});Object.assign(videoForm,{linkKey:'',externalVideoId:''});videoCreateDialog.value=false;ElMessage.success('视频已登记');await refreshVideos()}
function openPublish(row){selectedVideo.value=row;Object.assign(publishForm,{platform:'',externalPublishId:'',publishUrl:'',publishedAt:''});publishDialog.value=true}
async function publishVideo(){await post(`/fan/videos/${selectedVideo.value.id}/publications`,publishForm);publishDialog.value=false;ElMessage.success('发布记录已保存');await refreshVideos()}
function openSummary(row){selectedOrder.value=row;summary.value=null;summaryDialog.value=true}
async function loadSummary(){if(!summaryForm.source||!summaryForm.asOf){ElMessage.warning('请填写来源和截止时间');return}summary.value=await get(`/fan/orders/${selectedOrder.value.id}/summary?source=${encodeURIComponent(summaryForm.source)}&asOf=${encodeURIComponent(summaryForm.asOf)}`)}
function openFee(row){selectedOrder.value=row;Object.assign(feeForm,{actualFee:0,reason:''});feeDialog.value=true}
async function submitFee(){await post(`/fan/orders/${selectedOrder.value.id}/fee-adjustments`,feeForm);feeDialog.value=false;ElMessage.success('已提交商家确认')}
function openSettlement(row){selectedOrder.value=row;settlementDialog.value=true}
async function createSettlement(){await post(`/fan/settlements/order/${selectedOrder.value.id}`,settlementForm);settlementDialog.value=false;ElMessage.success('结算草稿已创建');tab.value='settlements';await reload()}
async function approveSettlement(row){await ElMessageBox.confirm('确认结算金额无误？','确认结算');await post(`/fan/settlements/${row.id}/approve`,{version:row.version});ElMessage.success('已确认');await reload()}
function openReceipt(row){selectedSettlement.value=row;Object.assign(receiptForm,{amount:0.01,reference:'',note:''});receiptDialog.value=true}
async function recordReceipt(){await post(`/fan/settlements/${selectedSettlement.value.id}/receipts`,{...receiptForm,version:selectedSettlement.value.version});receiptDialog.value=false;ElMessage.success('收款已记录');await reload()}
async function settlementDetail(row){const d=await get(`/fan/settlements/${row.id}`);detailTitle.value='结算详情';detailText.value=JSON.stringify(d,null,2);detailDialog.value=true}
async function createImport(){if(!importFile.value||!imp.source||!imp.snapshotAt){ElMessage.warning('请选择文件并填写来源和时间');return}const data=new FormData();Object.entries(imp).forEach(([k,v])=>data.append(k,v));data.append('file',importFile.value);await request({url:'/fan/imports/async',method:'post',headers:{'Content-Type':'multipart/form-data',repeatSubmit:false},data});ElMessage.success('任务已提交，请刷新查看预览');await reload()}
async function showImport(row){const d=await get(`/fan/imports/async/${row.id}`);detailTitle.value='导入任务详情';let preview=d.preview_json?JSON.parse(d.preview_json):[];detailText.value=JSON.stringify({状态:status(d.state),总行数:d.total_rows,预览:preview,结果:d.result_json?JSON.parse(d.result_json):null,处理信息:d.error_message},null,2);detailDialog.value=true}
async function confirmImport(row){await ElMessageBox.confirm('确认导入这批带货数据？','确认导入');await post(`/fan/imports/async/${row.id}/confirm`,{version:row.version});ElMessage.success('导入任务已提交');await reload()}
async function retryImport(row){await post(`/fan/imports/async/${row.id}/retry`,{version:row.version});ElMessage.success('重试任务已提交');await reload()}
watch(()=>route.query.tab,v=>{if(v){tab.value=String(v);loadTab(tab.value)}})
onMounted(()=>loadTab(tab.value))
</script>
<style scoped>.ops-page{padding:28px;max-width:1600px;margin:auto}.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.page-head h1{font-size:25px;color:#173642;margin:8px 0}.page-head p,.hint{font-size:13px;color:#788b97;margin:0}.kicker{font-size:11px;font-weight:700;letter-spacing:.14em;color:#39997d}.ops-tabs{background:#fff;border:1px solid #e8eff0;border-radius:14px;padding:12px 20px 24px}.toolbar{display:flex;gap:10px;margin:8px 0 16px}.import-form{margin-top:8px}.hint{margin:0 0 15px}.rate-row{display:flex;align-items:center;gap:12px;margin-bottom:14px}.rate-row span:first-child{flex:1}.detail{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f8f9;padding:16px;border-radius:8px;max-height:450px;overflow:auto;color:#314d59}.summary-line{padding:16px;background:#f0f7f4;border-radius:8px;margin-bottom:16px}.el-select{width:100%}@media(max-width:700px){.ops-page{padding:14px}.page-head{align-items:flex-start;gap:12px}.ops-tabs{padding:8px}}</style>
